type Result = { exitCode: number; stdout: string; stderr: string };
/** Provisioning judges exit codes itself (its recovery branch reads a failed `workspace add`),
 * so its `run` gets the raw result; the setup commands below use `must` and throw. */
async function spawnResult(
  cmd: string[],
  opts?: { cwd?: string; env?: Readonly<Record<string, string>> }
): Promise<Result> {
  const child = Bun.spawn(cmd, {
    cwd: opts?.cwd,
    env: opts?.env ? { ...process.env, ...opts.env } : undefined,
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
    child.exited,
  ]);
  return { exitCode, stdout, stderr };
}
async function must(cmd: string[], cwd?: string): Promise<Result> {
  const result = await spawnResult(cmd, { cwd });
  if (result.exitCode !== 0) throw new Error(`${cmd.join(" ")}\n${result.stderr}`);
